#include <print>
#include <algorithm>
#include <iterator>
#include <vector>

int main() {
    std::vector<int> a = {1, 2, 3, 4, 5}, b = {3, 4, 5, 6, 7};
    std::vector<int> diff;
    std::set_difference(a.begin(), a.end(), b.begin(), b.end(), std::back_inserter(diff));
    for (int v : diff) std::print("{} ", v);
    std::println("← a 减 b");
    std::vector<int> p = {3, 1, 5, 2, 4}, q = {4, 5, 1, 7, 3};
    std::vector<int> inter;
    std::set_intersection(p.begin(), p.end(), q.begin(), q.end(), std::back_inserter(inter));
    for (int v : inter) std::println("{}", v);
    // 不排序时双指针敢把 3 当场判死，对面尾巴里那个 3 就没读到
    return 0;
}

